insert into public.exercises (name, slug, description, instructions, main_muscle, secondary_muscles, equipment, difficulty, type, image_url, images, force, mechanic, common_mistakes, tips, recommended_sets, recommended_reps, recommended_rest_seconds, alternatives) values
('Barbell Bench Press - Medium Grip','barbell-bench-press---medium-grip','A compound push exercise.',ARRAY['Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.','After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Bench_Press_-_Medium_Grip/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Barbell Incline Bench Press - Medium Grip','barbell-incline-bench-press---medium-grip','A compound push exercise.',ARRAY['Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on you upper chest.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Behind Head Chest Stretch','behind-head-chest-stretch','An isolation static exercise.',ARRAY['Sit upright on the floor with your partner behind you.','Place your hands behind your hand, and push your elbows back as far as you can. Your partner should hold your elbows. This will be your starting position.','Gently attempt to pull your elbows forward with your hands still behind your head for 10 or more seconds. Your partner should prevent your elbows from moving.','Now, relax your muscles and have your partner gently pull the elbows back as far as it comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.']::text[],'pecho',ARRAY['hombros']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Behind_Head_Chest_Stretch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Behind_Head_Chest_Stretch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Behind_Head_Chest_Stretch/1.jpg']::text[],'Estático','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Bench Press - With Bands','bench-press---with-bands','A compound push exercise.',ARRAY['Using a flat bench secure a band under the leg of the bench that is nearest to your head.','Once the band is secure, grab it by both handles and lie down on the bench.','Extend your arms so that you are holding the band handles in front of you at shoulder width.','Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.','Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at all times.','As you breathe out, bring the handles up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions of your training program.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['bandas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_-_With_Bands/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_-_With_Bands/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_-_With_Bands/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Bodyweight Flyes','bodyweight-flyes','An isolation push exercise.',ARRAY['Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll.','Assume a push-up position over the bars, supporting your weight on your toes and hands with your arms extended and body straight.','Place your hands on the bars. This will be your starting position.','Using a slow and controlled motion, move your hands away from the midline of your body, rolling the bars apart. Inhale during this portion of the motion.','After moving the bars as far apart as you can, return to the starting position by pulling them back together. Exhale as you perform this movement.']::text[],'pecho',ARRAY['abdomen','hombros','triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bodyweight_Flyes/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bodyweight_Flyes/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bodyweight_Flyes/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Butterfly','butterfly','An isolation pull exercise.',ARRAY['Sit on the machine with your back flat on the pad.','Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.','Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.','Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.','Repeat for the recommended amount of repetitions.']::text[],'pecho',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Butterfly/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Butterfly/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Butterfly/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Cable Crossover','cable-crossover','An isolation push exercise.',ARRAY['To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.','Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.','With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.','Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.','Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions.']::text[],'pecho',ARRAY['hombros']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Crossover/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Crossover/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Crossover/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Cable Iron Cross','cable-iron-cross','An isolation push exercise.',ARRAY['Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.','Stand directly between both pulleys with your arms extended out to your sides. Your head and chest should be up while your arms form a "T". This will be your starting position.','Keeping the elbows extended, pull your arms straight to your sides.','Return your arms back to the starting position after a pause at the peak contraction.','Continue the movement for the prescribed number of repetitions.']::text[],'pecho',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Iron_Cross/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Iron_Cross/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Iron_Cross/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Chain Press','chain-press','A compound push exercise.',ARRAY['Begin by connecting the chains to the cable handle attachments. Position yourself on the flat bench in the same position as for a dumbbell press. Your wrists should be pronated and arms perpendicular to the floor. This will be your starting position.','Lower the chains by flexing the elbows, unloading some of the chain onto the floor.','Continue until your elbow forms a 90 degree angle, and then reverse the motion by extending through the elbow to lockout.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chain_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chain_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chain_Press/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Chest And Front Of Shoulder Stretch','chest-and-front-of-shoulder-stretch','An isolation static exercise.',ARRAY['Start off by standing with your legs together, holding a bodybar or a broomstick.','Take a slightly wider than shoulder width grip on the pole and hold it in front of you with your palms facing down.','Carefully lift the pole up and behind your head.']::text[],'pecho',ARRAY['hombros']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_And_Front_Of_Shoulder_Stretch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_And_Front_Of_Shoulder_Stretch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_And_Front_Of_Shoulder_Stretch/1.jpg']::text[],'Estático','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Chest Push from 3 point stance','chest-push-from-3-point-stance','A compound push exercise.',ARRAY['Begin in a three point stance, squatted down with your back flat and one hand on the ground. Place the medicine ball directly in front of you.','To begin, take your first step as you pull the ball to your chest, positioning both hands to prepare for the throw.','As you execute the second step, explosively release the ball forward as hard as possible.']::text[],'pecho',ARRAY['abdomen','hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_Push_from_3_point_stance/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_Push_from_3_point_stance/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_Push_from_3_point_stance/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Chest Push (multiple response)','chest-push-multiple-response','A compound push exercise.',ARRAY['Begin in a kneeling position facing a wall or utilize a partner. Hold the ball with both hands tight into the chest.','Execute the pass by exploding forward and outward with the hips while pushing the ball as hard as possible.','Follow through by falling forward, catching yourself with your hands.','Immediately return to an upright position. Repeat for the desired number of repetitions.']::text[],'pecho',ARRAY['abdomen','hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_Push_multiple_response/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_Push_multiple_response/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_Push_multiple_response/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Chest Push (single response)','chest-push-single-response','A compound push exercise.',ARRAY['Begin in a kneeling position holding the medicine ball with both hands tightly into the chest.','Execute the pass by exploding forward and outward with the hips while pushing the ball as far as possible.','Follow through by falling forward, catching yourself with your hands.']::text[],'pecho',ARRAY['abdomen','hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_Push_single_response/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_Push_single_response/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_Push_single_response/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Chest Push with Run Release','chest-push-with-run-release','A compound push exercise.',ARRAY['Begin in an athletic stance with the knees bent, hips back, and back flat. Hold the medicine ball near your legs. This will be your starting position.','While taking your first step draw the medicine ball into your chest.','As you take the second step, explosively push the ball forward, immediately sprinting for 10 yards after the release. If you are really fast, you can catch your own pass!']::text[],'pecho',ARRAY['abdomen','hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_Push_with_Run_Release/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_Push_with_Run_Release/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_Push_with_Run_Release/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Chest Stretch on Stability Ball','chest-stretch-on-stability-ball','An isolation static exercise.',ARRAY['Get on your hands and knees next to an exercise ball.','Place your elbows on top of the ball, keeping your arm out to your side. This will be your starting position.','Lower your torso towards the floor, keeping your elbow on top of the ball. Hold the stretch for 20-30 seconds, and repeat with the other arm.']::text[],'pecho',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_Stretch_on_Stability_Ball/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_Stretch_on_Stability_Ball/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chest_Stretch_on_Stability_Ball/1.jpg']::text[],'Estático','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Cross Over - With Bands','cross-over---with-bands','A compound push exercise.',ARRAY['Secure an exercise band around a stationary post.','While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band.','Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter "T") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will be your starting position.','While keeping your arms straight, bring them across your chest in a semicircular motion to the front as you exhale and flex your pecs. Hold the contraction for a second.','Slowly return to the starting position as you inhale.','Perform for the recommended amount of repetitions.']::text[],'pecho',ARRAY['biceps','hombros']::muscle_group_type[],ARRAY['bandas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross_Over_-_With_Bands/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross_Over_-_With_Bands/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross_Over_-_With_Bands/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Decline Push-Up','decline-push-up','A compound push exercise.',ARRAY['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.','Next, lower yourself downward until your chest almost touches the floor as you inhale.','Now breathe out and press your upper body back up to the starting position while squeezing your chest.','After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Push-Up/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Push-Up/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Push-Up/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dips - Chest Version','dips---chest-version','A compound push exercise.',ARRAY['For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.','While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.','Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.','Repeat the movement for the prescribed amount of repetitions.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dips_-_Chest_Version/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dips_-_Chest_Version/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dips_-_Chest_Version/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Drop Push','drop-push','A compound push exercise.',ARRAY['Position low boxes or other platforms 2-3 feet apart.','Move to a pushup position between them, supporting yourself by placing your hands on the boxes.','With good posture, drop from the platforms by pressing up and moving your hands to shoulder width, cushioning your landing by absorbing the impact through the arm.']::text[],'pecho',ARRAY['hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Drop_Push/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Drop_Push/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Drop_Push/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dumbbell Flyes','dumbbell-flyes','An isolation push exercise.',ARRAY['Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.','Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you''re pressing them, but stop and hold just before you lock out. This will be your starting position.','With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.','Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.','Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[],'pecho',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Flyes/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Flyes/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Flyes/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Dynamic Chest Stretch','dynamic-chest-stretch','An isolation pull exercise.',ARRAY['Stand with your hands together, arms extended directly in front of you. This will be your starting position.','Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion. Repeat 5-10 times, increasing speed as you do so.']::text[],'pecho',ARRAY['espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dynamic_Chest_Stretch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dynamic_Chest_Stretch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dynamic_Chest_Stretch/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Elbows Back','elbows-back','An isolation static exercise.',ARRAY['Stand up straight.','Place both hands on your lower back, fingers pointing downward and elbows out.','Then gently pull your elbows back aiming to touch them together.']::text[],'pecho',ARRAY['hombros']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Elbows_Back/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Elbows_Back/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Elbows_Back/1.jpg']::text[],'Estático','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Alternating Kettlebell Row','alternating-kettlebell-row','An isolation pull exercise.',ARRAY['Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles.','Pull one kettlebell off of the floor while holding on to the other kettlebell. Retract the shoulder blade of the working side, as you flex the elbow, drawing the kettlebell towards your stomach or rib cage.','Lower the kettlebell in the working arm and repeat with your other arm.']::text[],'espalda',ARRAY['biceps','espalda']::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Kettlebell_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Kettlebell_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Kettlebell_Row/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Alternating Renegade Row','alternating-renegade-row','A compound pull exercise.',ARRAY['Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.','Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.','Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps.']::text[],'espalda',ARRAY['abdomen','biceps','pecho','espalda','triceps']::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Renegade_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Renegade_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Renegade_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Atlas Stone Trainer','atlas-stone-trainer','A compound pull exercise.',ARRAY['This trainer is effective for developing Atlas Stone strength for those who don''t have access to stones, and are typically made from bar ends or heavy pipe.','Begin by loading the desired weight onto the bar. Straddle the weight, wrapping your arms around the implement, bending at the hips.','Begin by pulling the weight up past the knees, extending through the hips. As the weight clears the knees, it can be lapped by resting it on your thighs and sitting back, hugging it tightly to your chest.','Finish the movement by extending through your hips and knees to raise the weight as high as possible. The weight can be returned to the lap or to the ground for successive repetitions.']::text[],'espalda',ARRAY['biceps','gluteos','piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Atlas_Stone_Trainer/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Atlas_Stone_Trainer/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Atlas_Stone_Trainer/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Atlas Stones','atlas-stones','A compound pull exercise.',ARRAY['Begin with the atlas stone between your feet. Bend at the hips to wrap your arms vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold.','Pulling the stone into your torso, drive through the back half of your feet to pull the stone from the ground.','As the stone passes the knees, lap it by sitting backward, pulling the stone on top of your thighs.','Sit low, getting the stone high onto your chest as you change your grip to reach over the stone. Stand, driving through with your hips. Close distance to the loading platform, and lean back, extending the hips to get the stone as high as possible.']::text[],'espalda',ARRAY['abdomen','piernas','biceps','gluteos','espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Atlas_Stones/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Atlas_Stones/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Atlas_Stones/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Axle Deadlift','axle-deadlift','A compound pull exercise.',ARRAY['Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an over/under grip.','With your feet and your grip set, take a big breath and then lower your hips and flex the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.','After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','Lower the bar by bending at the hips and guiding it to the floor.']::text[],'espalda',ARRAY['biceps','gluteos','piernas','espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Axle_Deadlift/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Axle_Deadlift/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Axle_Deadlift/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Band Assisted Pull-Up','band-assisted-pull-up','A compound push exercise.',ARRAY['Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.','Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position.','Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.','After a brief pause, return to the starting position.']::text[],'espalda',ARRAY['abdomen','biceps','espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Assisted_Pull-Up/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Assisted_Pull-Up/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Assisted_Pull-Up/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Barbell Shrug','barbell-shrug','An isolation pull exercise.',ARRAY['Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.','Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.','Slowly return to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Shrug/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Shrug/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Shrug/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Barbell Shrug Behind The Back','barbell-shrug-behind-the-back','An isolation pull exercise.',ARRAY['Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position.','Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps. The arms should remain stretched out at all times.','Slowly return to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY['biceps','espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Shrug_Behind_The_Back/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Shrug_Behind_The_Back/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Shrug_Behind_The_Back/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Bodyweight Mid Row','bodyweight-mid-row','A compound pull exercise.',ARRAY['Begin by taking a medium to wide grip on a pull-up apparatus with your palms facing away from you. From a hanging position, tuck your knees to your chest, leaning back and getting your legs over your side of the pull-up apparatus. This will be your starting position.','Beginning with your arms straight, flex the elbows and retract the shoulder blades to raise your body up until your legs contact the pull-up apparatus.','After a brief pause, return to the starting position.']::text[],'espalda',ARRAY['biceps','espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bodyweight_Mid_Row/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bodyweight_Mid_Row/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bodyweight_Mid_Row/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Cable Incline Pushdown','cable-incline-pushdown','An isolation pull exercise.',ARRAY['Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.','Grasp the straight bar attachment overhead with a pronated (overhand; palms down) shoulder width grip and extend your arms in front of you. The bar should be around 2 inches away from your upper thighs. This will be your starting position.','Keeping the upper arms stationary, lift your arms back in a semi circle until the bar is straight over your head. Breathe in during this portion of the movement.','Slowly go back to the starting position using your lats and hold the contraction once you reach the starting position. Breathe out during the execution of this movement.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Incline_Pushdown/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Incline_Pushdown/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Incline_Pushdown/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Cable Shrugs','cable-shrugs','An isolation pull exercise.',ARRAY['Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip.','Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position.','Lift the bar by elevating the shoulders as high as possible as you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the bar. Only the shoulders should be moving up and down.','Lower the bar back to the original position.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Shrugs/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Shrugs/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Shrugs/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Calf-Machine Shoulder Shrug','calf-machine-shoulder-shrug','An isolation pull exercise.',ARRAY['Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position.','Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second.','Slowly return to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Calf-Machine_Shoulder_Shrug/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Calf-Machine_Shoulder_Shrug/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Calf-Machine_Shoulder_Shrug/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Cat Stretch','cat-stretch','An isolation static exercise.',ARRAY['Position yourself on the floor on your hands and knees.','Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.','Hold for 15 seconds.']::text[],'espalda',ARRAY['espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cat_Stretch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cat_Stretch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cat_Stretch/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Catch and Overhead Throw','catch-and-overhead-throw','A compound push exercise.',ARRAY['Begin standing while facing a wall or a partner.','Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward.','Ensure that you follow your throw through, being prepared to receive your rebound from your throw. If you are throwing against the wall, make sure that you stand close enough to the wall to receive the rebound, and aim a little higher than you would with a partner.']::text[],'espalda',ARRAY['abdomen','pecho','hombros']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Catch_and_Overhead_Throw/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Catch_and_Overhead_Throw/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Catch_and_Overhead_Throw/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Chair Lower Back Stretch','chair-lower-back-stretch','An isolation static exercise.',ARRAY['Sit upright on a chair.','Bend to one side with your arm over your head. You can hold onto the chair with your free hand.','Hold for 10 seconds, and repeat for your other side.']::text[],'espalda',ARRAY['espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chair_Lower_Back_Stretch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chair_Lower_Back_Stretch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chair_Lower_Back_Stretch/1.jpg']::text[],'Estático','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Child''s Pose','childs-pose','An isolation static exercise.',ARRAY['Get on your hands and knees, walk your hands in front of you.','Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine.','Once you settle onto your heels, bring your hands next to your feet and relax. "breathe" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems.']::text[],'espalda',ARRAY['gluteos','espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Childs_Pose/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Childs_Pose/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Childs_Pose/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Crossover Reverse Lunge','crossover-reverse-lunge','An isolation pull exercise.',ARRAY['Stand with your feet shoulder width apart. This will be your starting position.','Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg.','After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion.']::text[],'espalda',ARRAY['abdomen','gluteos','piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Crossover_Reverse_Lunge/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Crossover_Reverse_Lunge/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Crossover_Reverse_Lunge/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Dancer''s Stretch','dancers-stretch','An isolation static exercise.',ARRAY['Sit up on the floor.','Cross your right leg over your left, keeping the knee bent. Your left leg is straight and down on the floor.','Place your left arm on your right leg and your right hand on the floor.','Rotate your upper body to the right, and hold for 10-20 seconds. Switch sides.']::text[],'espalda',ARRAY['gluteos']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dancers_Stretch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dancers_Stretch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dancers_Stretch/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Deadlift with Bands','deadlift-with-bands','A compound pull exercise.',ARRAY['To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy dumbbells or a rack.','With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','Lower the bar by bending at the hips and guiding it to the floor.']::text[],'espalda',ARRAY['biceps','gluteos','piernas','espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Deadlift_with_Bands/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Deadlift_with_Bands/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Deadlift_with_Bands/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Deadlift with Chains','deadlift-with-chains','A compound pull exercise.',ARRAY['You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift.','Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.','Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','Lower the bar by bending at the hips and guiding it to the floor.']::text[],'espalda',ARRAY['biceps','gluteos','piernas','espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Deadlift_with_Chains/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Deadlift_with_Chains/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Deadlift_with_Chains/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dumbbell Shrug','dumbbell-shrug','An isolation pull exercise.',ARRAY['Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.','Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.','Lower the dumbbells back to the original position.','Repeat for the recommended amount of repetitions.']::text[],'espalda',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Shrug/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Shrug/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Shrug/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Dynamic Back Stretch','dynamic-back-stretch','An isolation pull exercise.',ARRAY['Stand with your feet shoulder width apart. This will be your starting position.','Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head.']::text[],'espalda',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dynamic_Back_Stretch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dynamic_Back_Stretch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dynamic_Back_Stretch/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('90/90 Hamstring','9090-hamstring','An isolation push exercise.',ARRAY['Lie on your back, with one leg extended straight out.','With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.','Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.','Repeat for 10-20 repetitions, and then switch to the other leg.']::text[],'piernas',ARRAY['piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/90_90_Hamstring/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/90_90_Hamstring/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/90_90_Hamstring/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Adductor','adductor','An isolation static exercise.',ARRAY['Lie face down with one leg on a foam roll.','Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated.','While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg.']::text[],'piernas',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Adductor/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Adductor/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Adductor/1.jpg']::text[],'Estático','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Adductor/Groin','adductorgroin','An isolation static exercise.',ARRAY['Lie on your back with your feet raised towards the ceiling.','Have your partner hold your feet or ankles. Abduct your legs as far as you can. This will be your starting position.','Attempt to squeeze your legs together for 10 or more seconds, while your partner prevents you from doing so.','Now, relax the muscles in your legs as your partner pushes your feet apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.']::text[],'piernas',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Adductor_Groin/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Adductor_Groin/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Adductor_Groin/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('All Fours Quad Stretch','all-fours-quad-stretch','An isolation static exercise.',ARRAY['Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand.','Use your hand to hold the foot or ankle, keeping the knee fully flexed, stretching the quadriceps and hip flexors.','Focus on extending your hips, thrusting them towards the floor. Hold for 10-20 seconds and then switch sides.']::text[],'piernas',ARRAY['piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/All_Fours_Quad_Stretch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/All_Fours_Quad_Stretch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/All_Fours_Quad_Stretch/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Alternate Leg Diagonal Bound','alternate-leg-diagonal-bound','A compound push exercise.',ARRAY['Assume a comfortable stance with one foot slightly in front of the other.','Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound.','It may help to use a line on the ground to guage distance from side to side.','Repeat the sequence with the other leg.']::text[],'piernas',ARRAY['gluteos','piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Leg_Diagonal_Bound/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Leg_Diagonal_Bound/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Leg_Diagonal_Bound/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Ankle Circles','ankle-circles','An isolation pull exercise.',ARRAY['Use a sturdy object like a squat rack to hold yourself.','Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Tip: One circle equals 1 repetition. Breathe normally as you perform the movement.','When you are done with the right foot, then repeat with the left leg.']::text[],'piernas',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ankle_Circles/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ankle_Circles/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ankle_Circles/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Anterior Tibialis-SMR','anterior-tibialis-smr','An isolation static exercise.',ARRAY['Begin seated on the ground with your legs bent and your feet on the floor.','Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins. Work from just below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat on the other leg.']::text[],'piernas',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Anterior_Tibialis-SMR/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Anterior_Tibialis-SMR/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Anterior_Tibialis-SMR/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Backward Drag','backward-drag','A compound pull exercise.',ARRAY['Load a sled with the desired weight, attaching a rope or straps to the sled that you can hold onto.','Begin the exercise by moving backwards for a given distance. Leaning back, extend through the legs for short steps to move as quickly as possible.']::text[],'piernas',ARRAY['piernas','biceps','gluteos','espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Backward_Drag/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Backward_Drag/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Backward_Drag/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Balance Board','balance-board','A compound push exercise.',ARRAY['Place a balance board in front of you.','Stand up on it and try to balance yourself.','Hold the balance for as long as desired.']::text[],'piernas',ARRAY['piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Balance_Board/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Balance_Board/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Balance_Board/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Ball Leg Curl','ball-leg-curl','An isolation pull exercise.',ARRAY['Begin on the floor laying on your back with your feet on top of the ball.','Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position.','Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.','Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings.','After a brief pause, return to the starting position.']::text[],'piernas',ARRAY['piernas','gluteos']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ball_Leg_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ball_Leg_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ball_Leg_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Band Hip Adductions','band-hip-adductions','An isolation pull exercise.',ARRAY['Anchor a band around a solid post or other object.','Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.','Stand up straight and hold onto the post if needed. This will be your starting position.','Keeping the knee straight, raise your right legs out to the side as far as you can.','Return to the starting position and repeat for the desired rep count.','Switch sides.']::text[],'piernas',ARRAY[]::muscle_group_type[],ARRAY['bandas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Hip_Adductions/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Hip_Adductions/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Hip_Adductions/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Barbell Seated Calf Raise','barbell-seated-calf-raise','An isolation push exercise.',ARRAY['Place a block about 12 inches in front of a flat bench.','Sit on the bench and place the ball of your feet on the block.','Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position.','Raise up on your toes as high as possible as you squeeze the calves and as you breathe out.','After a second contraction, slowly go back to the starting position. Tip: To get maximum benefit stretch your calves as far as you can.','Repeat for the recommended amount of repetitions.']::text[],'piernas',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Seated_Calf_Raise/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Seated_Calf_Raise/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Seated_Calf_Raise/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Barbell Squat To A Bench','barbell-squat-to-a-bench','A compound push exercise.',ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat bench or a box behind you. The flat bench is used to teach you to set your hips back and to hit depth.','','Then, set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).','Begin to slowly lower the bar by bending the knees and sitting your hips back as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs and extend the hips to go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'piernas',ARRAY['piernas','gluteos','espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Squat_To_A_Bench/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Squat_To_A_Bench/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Squat_To_A_Bench/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Bear Crawl Sled Drags','bear-crawl-sled-drags','A compound push exercise.',ARRAY['Wearing either a harness or a loose weight belt, attach the chain to the back so that you will be facing away from the sled. Bend down so that your hands are on the ground. Your back should be flat and knees bent. This is your starting position.','Begin by driving with legs, alternating left and right. Use your hands to maintain balance and to help pull. Try to keep your back flat as you move over a given distance.']::text[],'piernas',ARRAY['piernas','gluteos']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bear_Crawl_Sled_Drags/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bear_Crawl_Sled_Drags/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bear_Crawl_Sled_Drags/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Bench Sprint','bench-sprint','A compound push exercise.',ARRAY['Stand on the ground with one foot resting on a bench or box with your heel close to the edge.','Push off with your foot on top of the bench, extending through the hip and knee.','Land with the opposite foot on top of the box, returning your other foot back to the start position.','Continue alternating from one foot to another to complete the set.']::text[],'piernas',ARRAY['piernas','gluteos']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Sprint/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Sprint/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Sprint/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Bicycling','bicycling','An isolation push exercise.',ARRAY['To begin, seat yourself on the bike and adjust the seat to your height.']::text[],'piernas',ARRAY['piernas','gluteos']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bicycling/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bicycling/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bicycling/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Bicycling, Stationary','bicycling-stationary','An isolation push exercise.',ARRAY['To begin, seat yourself on the bike and adjust the seat to your height.','Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.']::text[],'piernas',ARRAY['piernas','gluteos']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bicycling_Stationary/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bicycling_Stationary/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bicycling_Stationary/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Bodyweight Walking Lunge','bodyweight-walking-lunge','A compound push exercise.',ARRAY['Begin standing with your feet shoulder width apart and your hands on your hips.','Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.','Drive through the heel of your lead foot and extend both knees to raise yourself back up.','Step forward with your rear foot, repeating the lunge on the opposite leg.']::text[],'piernas',ARRAY['piernas','gluteos']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bodyweight_Walking_Lunge/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bodyweight_Walking_Lunge/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bodyweight_Walking_Lunge/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Box Jump (Multiple Response)','box-jump-multiple-response','A compound push exercise.',ARRAY['Assume a relaxed stance facing the box or platform approximately an arm''s length away. Arms should be down at the sides and legs slightly bent.','Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform.','Immediately drop or jump back down to the original starting place; then repeat the sequence.']::text[],'piernas',ARRAY['gluteos','piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Jump_Multiple_Response/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Jump_Multiple_Response/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Jump_Multiple_Response/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Box Skip','box-skip','A compound push exercise.',ARRAY['You will need several boxes lined up about 8 feet apart.','Begin facing the first box with one leg slightly behind the other.','Drive off the back leg, attempting to gain as much height with the hips as possible.','Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box.','Then, step to the next box and repeat.']::text[],'piernas',ARRAY['gluteos','piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Skip/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Skip/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Skip/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Box Squat with Bands','box-squat-with-bands','A compound push exercise.',ARRAY['Begin in a power rack with a box at the appropriate height behind you. Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension. If dumbbells are used, secure them so that they don''t move. Also, ensure that the dumbbells you are using are heavy enough for the bands that you are using. Additional plates can be used to hold the dumbbells down. If more tension is needed, you can either widen the base on the floor or choke the bands. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.','Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.','With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.','Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack.']::text[],'piernas',ARRAY['gluteos','piernas','espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Squat_with_Bands/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Squat_with_Bands/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Squat_with_Bands/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Box Squat with Chains','box-squat-with-chains','A compound push exercise.',ARRAY['Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.','To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.','Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.','With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.','Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe.']::text[],'piernas',ARRAY['gluteos','piernas','espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Squat_with_Chains/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Squat_with_Chains/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Squat_with_Chains/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Alternating Deltoid Raise','alternating-deltoid-raise','An isolation push exercise.',ARRAY['In a standing position, hold a pair of dumbbells at your side.','Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.','Return the weights to your side.','On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height.','Return the weights to the starting position and continue alternating to the front and side.']::text[],'hombros',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Deltoid_Raise/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Deltoid_Raise/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Deltoid_Raise/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Arm Circles','arm-circles','An isolation push exercise.',ARRAY['Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.','Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.','Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction.']::text[],'hombros',ARRAY['espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Arm_Circles/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Arm_Circles/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Arm_Circles/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Back Flyes - With Bands','back-flyes---with-bands','A compound pull exercise.',ARRAY['Run a band around a stationary post like that of a squat rack.','Grab the band by the handles and stand back so that the tension in the band rises.','Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.','As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.','After a pause, go back to the original position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'hombros',ARRAY['espalda','triceps']::muscle_group_type[],ARRAY['bandas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Back_Flyes_-_With_Bands/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Back_Flyes_-_With_Bands/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Back_Flyes_-_With_Bands/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Backward Medicine Ball Throw','backward-medicine-ball-throw','A compound push exercise.',ARRAY['This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall.','Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs.','Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner.','Your partner can then roll the ball back to you. Repeat for the desired number of repetitions.']::text[],'hombros',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Backward_Medicine_Ball_Throw/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Backward_Medicine_Ball_Throw/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Backward_Medicine_Ball_Throw/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Band Pull Apart','band-pull-apart','An isolation pull exercise.',ARRAY['Begin with your arms extended straight out in front of you, holding the band with both hands.','Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.','Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.','Pause as you complete the movement, returning to the starting position under control.']::text[],'hombros',ARRAY['espalda']::muscle_group_type[],ARRAY['bandas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Pull_Apart/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Pull_Apart/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Pull_Apart/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Battling Ropes','battling-ropes','A compound push exercise.',ARRAY['For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with your arms extended at your side. This will be your starting position.','Initiate the movement by rapidly raising one arm to shoulder level as quickly as you can.','As you let that arm drop to the starting position, raise the opposite side.','Continue alternating your left and right arms, whipping the ropes up and down as fast as you can.']::text[],'hombros',ARRAY['pecho','biceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Battling_Ropes/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Battling_Ropes/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Battling_Ropes/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Bent Over Dumbbell Rear Delt Raise With Head On Bench','bent-over-dumbbell-rear-delt-raise-with-head-on-bench','An isolation pull exercise.',ARRAY['Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.','While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This will be your starting position.','Keeping your torso forward and stationary, and the arms straight with a slight bend at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. Caution: avoid swinging the torso or bringing the arms back as opposed to the side.','After a one second contraction at the top, slowly lower the dumbbells back to the starting position.','Repeat the recommended amount of repetitions.']::text[],'hombros',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Bent Over Low-Pulley Side Lateral','bent-over-low-pulley-side-lateral','An isolation pull exercise.',ARRAY['Select a weight and hold the handle of the low pulley with your right hand.','Bend at the waist until your torso is nearly parallel to the floor. Your legs should be slightly bent with your left hand placed on your lower left thigh. Your right arm should be hanging from your shoulder in front of you and with a slight bend at the elbow. This will be your starting position.','Raise your right arm, elbow slightly bent, to the side until the arm is parallel to the floor and in line with your right ear. Breathe out as you perform this step.','Slowly lower the weight back to the starting position as you breathe in.','Repeat for the recommended amount of repetitions and repeat the movement with the other arm.']::text[],'hombros',ARRAY['espalda']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Low-Pulley_Side_Lateral/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Low-Pulley_Side_Lateral/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Low-Pulley_Side_Lateral/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Bradford/Rocky Presses','bradfordrocky-presses','A compound push exercise.',ARRAY['Sit on a Military Press Bench with a bar at shoulder level with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. This is your starting position.','Once you pick up the barbell with the correct grip, lift the bar up over your head by locking your arms.','Now lower the bar down to the back of the head slowly as you inhale.','Lift the bar back up to the starting position as you exhale.','Lower the bar down to the starting position slowly as you inhale. This is one repetition.','Alternate in this manner until you complete the recommended amount of repetitions.']::text[],'hombros',ARRAY['triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bradford_Rocky_Presses/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bradford_Rocky_Presses/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bradford_Rocky_Presses/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Cable Rear Delt Fly','cable-rear-delt-fly','An isolation pull exercise.',ARRAY['Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.','Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.','Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.','Pause at the end of the motion before returning the handles to the start position.']::text[],'hombros',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Rear_Delt_Fly/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Rear_Delt_Fly/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Rear_Delt_Fly/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Cable Seated Lateral Raise','cable-seated-lateral-raise','An isolation pull exercise.',ARRAY['Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.','Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.','Bend forward while keeping your back flat and rest your torso on the thighs.','Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.','While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.','Slowly lower your arms to the starting position as you inhale.','Repeat for the recommended amount of repetitions. Tip: Maintain upper arms perpendicular to torso and a fixed elbow position (10 degree to 30 degree angle) throughout exercise.']::text[],'hombros',ARRAY['espalda']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Seated_Lateral_Raise/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Seated_Lateral_Raise/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Seated_Lateral_Raise/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Car Drivers','car-drivers','An isolation push exercise.',ARRAY['While standing upright, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended straight out in front of you. This will be your starting position.','Initiate the movement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side.','Reverse the motion, turning it all the way to the opposite side.','Repeat for the recommended amount of repetitions.']::text[],'hombros',ARRAY['biceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Car_Drivers/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Car_Drivers/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Car_Drivers/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Chair Upper Body Stretch','chair-upper-body-stretch','An isolation static exercise.',ARRAY['Sit on the edge of a chair, gripping the back of it.','Straighten your arms, keeping your back straight, and pull your upper body forward so you feel a stretch. Hold for 20-30 seconds.']::text[],'hombros',ARRAY['biceps','pecho']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chair_Upper_Body_Stretch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chair_Upper_Body_Stretch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chair_Upper_Body_Stretch/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Chin To Chest Stretch','chin-to-chest-stretch','An isolation static exercise.',ARRAY['Get into a seated position on the floor.','Place both hands at the rear of your head, fingers interlocked, thumbs pointing down and elbows pointing straight ahead. Slowly pull your head down to your chest. Hold for 20-30 seconds.']::text[],'hombros',ARRAY['espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chin_To_Chest_Stretch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chin_To_Chest_Stretch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chin_To_Chest_Stretch/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Circus Bell','circus-bell','A compound push exercise.',ARRAY['The circus bell is an oversized dumbbell with a thick handle. Begin with the dumbbell between your feet, and grip the handle with both hands.','Clean the dumbbell by extending through your hips and knees to deliver the implement to the desired shoulder, letting go with the extra hand.','Ensure that you get one of the dumbbell heads behind the shoulder to keep from being thrown off balance. To raise it overhead, dip by flexing the knees, and the drive upwards as you extend the dumbbell overhead, leaning slightly away from it as you do so.','Carefully guide the bell back to the floor, keeping it under control as much as possible. It is best to perform this event on a thick rubber mat to prevent damage to the floor.']::text[],'hombros',ARRAY['biceps','gluteos','piernas','espalda','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Circus_Bell/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Circus_Bell/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Circus_Bell/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Clean and Jerk','clean-and-jerk','A compound push exercise.',ARRAY['With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.','Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.','As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.','Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.','The second phase is the jerk, which raises the weight overhead. Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.','Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.','At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position.']::text[],'hombros',ARRAY['abdomen','gluteos','piernas','espalda','triceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_and_Jerk/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_and_Jerk/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_and_Jerk/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Crucifix','crucifix','An isolation static exercise.',ARRAY['In the crucifix, you statically hold weights out to the side for time. While the event can be practiced using dumbbells, it is best to practice with one of the various implements used, such as axes and hammers, as it feels different.','Begin standing, and raise your arms out to the side holding the implements. Your arms should be parallel to the ground. In competition, judges or sensors are used to let you know when you break parallel. Hold for as long as you can. Typically, the weights should be heavy enough that you fail in 30-60 seconds.']::text[],'hombros',ARRAY['biceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Crucifix/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Crucifix/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Crucifix/1.jpg']::text[],'Estático','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Double Kettlebell Snatch','double-kettlebell-snatch','A compound pull exercise.',ARRAY['Place two kettlebells behind your feet. Bend your knees and sit back to pick up the kettlebells.','Swing the kettlebells between your legs forcefully and reverse the direction.','Drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.']::text[],'hombros',ARRAY['gluteos','piernas']::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Kettlebell_Snatch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Kettlebell_Snatch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Kettlebell_Snatch/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dumbbell Incline Shoulder Raise','dumbbell-incline-shoulder-raise','An isolation push exercise.',ARRAY['Sit on an Incline Bench while holding a dumbbell on each hand on top of your thighs.','Lift your legs up to kick the weights to your shoulders and lean back. Position the dumbbells above your shoulders with your arms extended. The arms should be perpendicular to the floor with your palms facing forward and knuckles pointing towards the ceiling. This will be your starting position.','While keeping the arms straight and locked, lift the dumbbells by raising the shoulders from the bench as you breathe out.','Bring back the dumbbells to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[],'hombros',ARRAY['triceps']::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Incline_Shoulder_Raise/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Incline_Shoulder_Raise/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Incline_Shoulder_Raise/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Dumbbell Lying One-Arm Rear Lateral Raise','dumbbell-lying-one-arm-rear-lateral-raise','An isolation pull exercise.',ARRAY['While holding a dumbbell in one hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench. The other hand can be used to hold to the leg of the bench for stability.','Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position.','Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.','Slowly lower the dumbbell to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'hombros',ARRAY['espalda']::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Dumbbell Lying Rear Lateral Raise','dumbbell-lying-rear-lateral-raise','An isolation pull exercise.',ARRAY['While holding a dumbbell in each hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench.','Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position.','Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.','Slowly lower the dumbbells to the starting position as you inhale.','Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[],'hombros',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Rear_Lateral_Raise/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Rear_Lateral_Raise/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Rear_Lateral_Raise/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Dumbbell Scaption','dumbbell-scaption','An isolation push exercise.',ARRAY['This corrective exercise strengthens the muscles that stabilize your shoulder blade. Hold a light weight in each hand, hanging at your sides. Your thumbs should pointing up.','Begin the movement raising your arms out in front of you, about 30 degrees off center. Your arms should be fully extended as you perform the movement.','Continue until your arms are parallel to the ground, and then return to the starting position.']::text[],'hombros',ARRAY['espalda']::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Scaption/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Scaption/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Scaption/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Brachialis-SMR','brachialis-smr','An isolation static exercise.',ARRAY['Lie on your side, with your upper arm against the foam roller. The upper arm should be more or less aligned with your body, with the outside of the bicep pressed against the foam roller.','Raise your hips off of the floor, supporting your weight on your arm and on your feet. Hold for 10-30 seconds, and then switch sides.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Brachialis-SMR/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Brachialis-SMR/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Brachialis-SMR/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Cable Hammer Curls - Rope Attachment','cable-hammer-curls---rope-attachment','An isolation pull exercise.',ARRAY['Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.','Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.','Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.','Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.','After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Hammer_Curls_-_Rope_Attachment/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Hammer_Curls_-_Rope_Attachment/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Hammer_Curls_-_Rope_Attachment/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Farmer''s Walk','farmers-walk','A compound push exercise.',ARRAY['There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren''t available. Begin by standing between the implements.','After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.','Walk taking short, quick steps, and don''t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible.']::text[],'biceps',ARRAY['abdomen','gluteos','piernas','espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Farmers_Walk/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Farmers_Walk/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Farmers_Walk/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Hammer Curls','hammer-curls','An isolation pull exercise.',ARRAY['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.','The palms of the hands should be facing your torso. This will be your starting position.','Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.','After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hammer_Curls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hammer_Curls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hammer_Curls/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Incline Dumbbell Curl','incline-dumbbell-curl','An isolation pull exercise.',ARRAY['Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.','While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.','Slowly begin to bring the dumbbells back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Incline Hammer Curls','incline-hammer-curls','An isolation pull exercise.',ARRAY['Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position.','Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary.','Continue to the top of the movement and pause, then slowly return to the start position.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Hammer_Curls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Hammer_Curls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Hammer_Curls/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Incline Inner Biceps Curl','incline-inner-biceps-curl','An isolation push exercise.',ARRAY['Hold a dumbbell in each hand and lie back on an incline bench.','The dumbbells should be at arm''s length hanging at your sides and your palms should be facing out. This will be your starting position.','Now as you exhale curl the weight outward and up while keeping your forearms in line with your side deltoids. Continue the curl until the dumbbells are at shoulder height and to the sides of your deltoids. Tip: The end of the movement should look similar to a double biceps pose.','After a second contraction at the top of the movement, start to inhale and slowly lower the weights back to the starting position using the same path used to bring them up.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Inner_Biceps_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Inner_Biceps_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Inner_Biceps_Curl/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Kneeling Forearm Stretch','kneeling-forearm-stretch','An isolation static exercise.',ARRAY['Start by kneeling on a mat with your palms flat and your fingers pointing back toward your knees.','Slowly lean back keeping your palms flat on the floor until you feel a stretch in your wrists and forearms. Hold for 20-30 seconds.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Forearm_Stretch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Forearm_Stretch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Forearm_Stretch/1.jpg']::text[],'Estático','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Lying Cable Curl','lying-cable-curl','An isolation pull exercise.',ARRAY['Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip.','Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight.','With your arms extended and your elbows close to your body slightly bend your arms. This will be your starting position.','While keeping your upper arms stationary and the elbows close to your body, curl the bar up slowly toward your chest as you breathe out and you squeeze the biceps.','After a second squeeze at the top of the movement, slowly return to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Cable_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Cable_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Cable_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Lying Close-Grip Bar Curl On High Pulley','lying-close-grip-bar-curl-on-high-pulley','An isolation pull exercise.',ARRAY['Place a flat bench in front of a high pulley or lat pulldown machine.','Hold the straight bar attachment using an underhand grip (palms up) that is about shoulder width.','Lie on your back with your head over the end of the bench.','Now extend your arms straight above your shoulders. Your torso and your arms should make a 90-degree angle and the elbows should be in. This will be your starting position.','As you breathe out, curl the bar down in a semicircular motion until it touches your chin. Squeeze the biceps for a second at the top contracted position. Tip: As you execute this motion only the forearms should move. At no time should the upper arms be moving at all. They are to remain perpendicular throughout the movement.','Return to starting position slowly.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Close-Grip_Bar_Curl_On_High_Pulley/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Close-Grip_Bar_Curl_On_High_Pulley/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Close-Grip_Bar_Curl_On_High_Pulley/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Lying High Bench Barbell Curl','lying-high-bench-barbell-curl','An isolation pull exercise.',ARRAY['Lie face forward on a tall flat bench while holding a barbell with a supinated grip (palms facing up). Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper chest is over the end of the bench and the barbell is hanging in front of you with the arms extended and perpendicular to the floor. This will be your starting position.','While keeping the elbows in and the upper arms stationary, curl the weight up in a semi-circular motion as you contract the biceps and exhale. Hold at the top of the movement for a second.','As you inhale, slowly go back to the starting position. Tip: Maintain full control of the weight at all times and avoid any swinging. Remember, only the forearms should move throughout the movement.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_High_Bench_Barbell_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_High_Bench_Barbell_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_High_Bench_Barbell_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Lying Supine Dumbbell Curl','lying-supine-dumbbell-curl','An isolation pull exercise.',ARRAY['Lie down on a flat bench face up while holding a dumbbell in each arm on top of your thighs.','Bring the dumbbells to the sides with the arms extended and the palms of the hands facing your thighs (neutral grip).','While keeping the arms close to your torso and elbows in, slowly lower your arms (as you keep them extended with a slight bend at the elbows) as far down towards the floor as you can go. Once you cannot go down any further, lock your upper arms in that position and that will be your starting position.','As you breathe out, slowly begin to curl the weights up as you simultaneously rotate your wrists so that the palms of the hands face up. Continue curling the weight until your biceps are fully contracted and squeeze hard at the top position for a second. Tip: Only the forearms should move. Upper arms should remain stationary and elbows should stay in throughout the movement.','Return back to the starting position very slowly.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Supine_Dumbbell_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Supine_Dumbbell_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Supine_Dumbbell_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Machine Bicep Curl','machine-bicep-curl','An isolation pull exercise.',ARRAY['Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.','Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm.','Pause at the top of the movement, and then slowly return the weight to the starting position.','Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Bicep_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Bicep_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Bicep_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Machine Preacher Curls','machine-preacher-curls','An isolation pull exercise.',ARRAY['Sit down on the Preacher Curl Machine and select the weight.','Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position.','Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Tip: Only the forearms should move. The upper arms should remain stationary and on the pad at all times.','Lower the handles slowly back to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Preacher_Curls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Preacher_Curls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Preacher_Curls/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('One Arm Dumbbell Preacher Curl','one-arm-dumbbell-preacher-curl','An isolation pull exercise.',ARRAY['Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.','As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched.','As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.','Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.','Switch arms and repeat the movement.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Arm_Dumbbell_Preacher_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Arm_Dumbbell_Preacher_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Arm_Dumbbell_Preacher_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Overhead Cable Curl','overhead-cable-curl','An isolation pull exercise.',ARRAY['To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side.','Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders.','Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle. Your arms should be fully extended and parallel to the floor with your feet positioned shoulder width apart from each other. Your body should be evenly aligned the handles. This is the starting position.','While exhaling, slowly squeeze the biceps on each side until your forearms and biceps touch.','While inhaling, move your forearms back to the starting position. Note: Your entire body is stationary during this exercise except for the forearms.','Repeat for the recommended amount of repetitions prescribed in your program.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Overhead_Cable_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Overhead_Cable_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Overhead_Cable_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Palms-Down Dumbbell Wrist Curl Over A Bench','palms-down-dumbbell-wrist-curl-over-a-bench','An isolation pull exercise.',ARRAY['Start out by placing two dumbbells on one side of a flat bench.','Kneel down on both of your knees so that your body is facing the flat bench.','Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Palms-Down Wrist Curl Over A Bench','palms-down-wrist-curl-over-a-bench','An isolation pull exercise.',ARRAY['Start out by placing a barbell on one side of a flat bench.','Kneel down on both of your knees so that your body is facing the flat bench.','Use your arms to grab the barbell with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Down_Wrist_Curl_Over_A_Bench/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Palms-Up Barbell Wrist Curl Over A Bench','palms-up-barbell-wrist-curl-over-a-bench','An isolation pull exercise.',ARRAY['Start out by placing a barbell on one side of a flat bench.','Kneel down on both of your knees so that your body is facing the flat bench.','Use your arms to grab the barbell with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Palms-Up Dumbbell Wrist Curl Over A Bench','palms-up-dumbbell-wrist-curl-over-a-bench','An isolation pull exercise.',ARRAY['Start out by placing two dumbbells on one side of a flat bench.','Kneel down on both of your knees so that your body is facing the flat bench.','Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Plate Pinch','plate-pinch','An isolation static exercise.',ARRAY['Grab two wide-rimmed plates and put them together with the smooth sides facing outward','Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. This is the starting position.','Squeeze the plate with your fingers and thumb. Hold this position for as long as you can.','Repeat for the recommended amount of sets prescribed in your program.','Switch arms and repeat the movements.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Plate_Pinch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Plate_Pinch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Plate_Pinch/1.jpg']::text[],'Estático','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Preacher Curl','preacher-curl','An isolation pull exercise.',ARRAY['To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.','With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.','As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.','As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Preacher_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Preacher_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Preacher_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Bench Press - Powerlifting','bench-press---powerlifting','A compound push exercise.',ARRAY['Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.','However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.','Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.','Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[],'triceps',ARRAY['pecho','biceps','espalda','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_-_Powerlifting/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_-_Powerlifting/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_-_Powerlifting/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Body-Up','body-up','An isolation push exercise.',ARRAY['Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.','Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement.','Slowly lower your forearms back to the ground by allowing the elbows to flex.','Repeat.']::text[],'triceps',ARRAY['abdomen','biceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Body-Up/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Body-Up/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Body-Up/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Body Tricep Press','body-tricep-press','An isolation push exercise.',ARRAY['Position a bar in a rack at chest height.','Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position.','Begin by flexing the elbow, lowering yourself towards the bar.','Pause, and then reverse the motion by extending the elbows.','Progress from bodyweight by adding chains over your shoulders.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Body_Tricep_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Body_Tricep_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Body_Tricep_Press/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Cable Incline Triceps Extension','cable-incline-triceps-extension','An isolation push exercise.',ARRAY['Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.','Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor.','Keeping the upper arms stationary, extend the arms as you flex the triceps. Breathe out during this portion of the movement and hold the contraction for a second.','Slowly go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Incline_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Incline_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Incline_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Cable Lying Triceps Extension','cable-lying-triceps-extension','An isolation push exercise.',ARRAY['Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down.','With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position.','Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in. Go down until the bar lightly touches your forehead. Breathe in as you perform this portion of the movement.','Flex the triceps as you lift the bar back to its starting position. Exhale as you perform this portion of the movement.','Hold for a second at the contracted position and repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Lying_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Lying_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Lying_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Cable One Arm Tricep Extension','cable-one-arm-tricep-extension','An isolation push exercise.',ARRAY['With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.','Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This will be your starting position.','As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Breathe out as you perform this movement. Tip: Only the forearms should move. Your upper arms should remain stationary at all times.','Squeeze the triceps and hold for a second in this contracted position.','Slowly return the handle to the starting position.','Repeat for the recommended amount of repetitions and then perform the same movement with the other arm.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_One_Arm_Tricep_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_One_Arm_Tricep_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_One_Arm_Tricep_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Cable Rope Overhead Triceps Extension','cable-rope-overhead-triceps-extension','An isolation push exercise.',ARRAY['Attach a rope to the bottom pulley of the pulley machine.','Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.','Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.','Return to the starting position by flexing your triceps as you breathe out.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Rope_Overhead_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Rope_Overhead_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Rope_Overhead_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Chain Handle Extension','chain-handle-extension','An isolation push exercise.',ARRAY['You will need two cable handle attachments and a flat bench, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat bench. Your elbows should be pointing straight up.','Begin by extending through the elbow, keeping your upper arm still, with your wrists pronated.','Pause at the lockout, and reverse the motion to return to the starting position.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chain_Handle_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chain_Handle_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chain_Handle_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Decline Dumbbell Triceps Extension','decline-dumbbell-triceps-extension','An isolation push exercise.',ARRAY['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.','Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.','As you breathe in and you keep the upper arms stationary (and elbows in), bring the dumbbells down slowly by moving your forearms in a semicircular motion towards you until your thumbs are next to your ears. Breathe in as you perform this portion of the movement.','Lift the dumbbells back to the starting position by contracting the triceps and exhaling.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Dumbbell_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Dumbbell_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Dumbbell_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Decline EZ Bar Triceps Extension','decline-ez-bar-triceps-extension','An isolation push exercise.',ARRAY['Secure your legs at the end of the decline bench and slowly lay down on the bench.','Using a close grip (a grip that is slightly less than shoulder width), lift the EZ bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.','As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.','Lift the bar back to the starting position by contracting the triceps and exhaling.','Repeat until the recommended amount of repetitions is performed.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_EZ_Bar_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_EZ_Bar_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_EZ_Bar_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Dips - Triceps Version','dips---triceps-version','A compound push exercise.',ARRAY['To get into the starting position, hold your body at arm''s length with your arms nearly locked above the bars.','Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.','Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.','Repeat the movement for the prescribed amount of repetitions.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dips_-_Triceps_Version/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dips_-_Triceps_Version/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dips_-_Triceps_Version/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dumbbell One-Arm Triceps Extension','dumbbell-one-arm-triceps-extension','An isolation push exercise.',ARRAY['Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.','Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the dumbbell or grabbing a fixed surface.','Rotate the wrist so that the palm of your hand is facing forward and the pinkie is facing the ceiling. This will be your starting position.','Slowly lower the dumbbell behind your head as you hold the upper arm stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.','Return to the starting position by flexing your triceps as you breathe out. Tip: It is imperative that only the forearm moves. The upper arm should remain at all times stationary next to your head.','Repeat for the recommended amount of repetitions and switch arms.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_One-Arm_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_One-Arm_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_One-Arm_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Dumbbell Tricep Extension -Pronated Grip','dumbbell-tricep-extension--pronated-grip','An isolation push exercise.',ARRAY['Lie down on a flat bench holding two dumbbells directly above your shoulders. Your arms should be fully extended and form a 90 degree angle from your torso and the floor.','The palms of your hands should be facing forward, and your elbows should be tucked in. This will be your starting position.','Now, inhale and slowly lower the dumbbells until they are near your ears. Be sure to keep your upper arms stationary and your elbows tucked in.','Then, exhale and use your triceps to return the weight to the starting position.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Tricep_Extension_-Pronated_Grip/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Tricep_Extension_-Pronated_Grip/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Tricep_Extension_-Pronated_Grip/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('EZ-Bar Skullcrusher','ez-bar-skullcrusher','An isolation push exercise.',ARRAY['Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.','Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.','Lift the bar back to the starting position by extending the elbow and exhaling.','Repeat.']::text[],'triceps',ARRAY['biceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/EZ-Bar_Skullcrusher/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/EZ-Bar_Skullcrusher/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/EZ-Bar_Skullcrusher/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Incline Barbell Triceps Extension','incline-barbell-triceps-extension','An isolation push exercise.',ARRAY['Hold a barbell with an overhand grip (palms down) that is a little closer together than shoulder width.','Lie back on an incline bench set at any angle between 45-75-degrees.','Bring the bar overhead with your arms extended and elbows in. The arms should be in line with the torso above the head. This will be your starting position.','Now lower the bar in a semicircular motion behind your head until your forearms touch your biceps. Inhale as you perform this movement. Tip: Keep your upper arms stationary and close to your head at all times. Only the forearms should move.','Return to the starting position as you breathe out and you contract the triceps. Hold the contraction for a second.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY['biceps']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Barbell_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Barbell_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Barbell_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Kneeling Cable Triceps Extension','kneeling-cable-triceps-extension','An isolation push exercise.',ARRAY['Place a bench sideways in front of a high pulley machine.','Hold a straight bar attachment above your head with your hands about 6 inches apart with your palms facing down.','Face away from the machine and kneel.','Place your head and the back of your upper arms on the bench. Your elbows should be bent with the forearms pointing towards the high pulley. This will be your starting position.','While keeping your upper arms close to your head at all times with the elbows in, press the bar out in a semicircular motion until the elbows are locked and your arms are parallel to the floor. Contract the triceps hard and keep this position for a second. Exhale as you perform this movement.','Slowly return to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Cable_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Cable_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Cable_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Low Cable Triceps Extension','low-cable-triceps-extension','An isolation push exercise.',ARRAY['Select the desired weight and lay down face up on the bench of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment.','Grab the outside of the rope ends with your palms facing each other (neutral grip).','Position your elbows so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torso. Tip: Keep the elbows in and make sure that the upper arms point to the ceiling while your forearms point towards the pulley above your head. This will be your starting position.','As you breathe out, extend your lower arms until they are straight and vertical. The upper arms and elbows remain stationary throughout the movement. Only the forearms should move. Contract the triceps hard for a second.','As you breathe in slowly return to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Low_Cable_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Low_Cable_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Low_Cable_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Lying Close-Grip Barbell Triceps Extension Behind The Head','lying-close-grip-barbell-triceps-extension-behind-the-head','An isolation push exercise.',ARRAY['While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head close to the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.','Extend your arms in front of you and slowly bring the bar back in a semi circular motion (while keeping the arms extended) to a position over your head. At the end of this step your arms should be overhead and parallel to the floor. This will be your starting position. Tip: Keep your elbows in at all times.','As you inhale, lower the bar by bending at the elbows and while keeping the upper arm stationary. Keep lowering the bar until your forearms are perpendicular to the floor.','As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion until the lower arms are also parallel to the floor. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Lying Close-Grip Barbell Triceps Press To Chin','lying-close-grip-barbell-triceps-press-to-chin','An isolation push exercise.',ARRAY['While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head off the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.','Extend your arms in front of you as you hold the barbell over your chest. The arms should be perpendicular to your torso (90-degree angle). This will be your starting position.','As you inhale, lower the bar in a semi-circular motion by bending at the elbows and while keeping the upper arm stationary and elbows in. Keep lowering the bar until it lightly touches your chin.','As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Lying Dumbbell Tricep Extension','lying-dumbbell-tricep-extension','An isolation push exercise.',ARRAY['Lie on a flat bench while holding two dumbbells directly in front of you. Your arms should be fully extended at a 90-degree angle from your torso and the floor. The palms should be facing in and the elbows should be tucked in. This is the starting position.','As you breathe in and you keep the upper arms stationary with the elbows in, slowly lower the weight until the dumbbells are near your ears.','At that point, while keeping the elbows in and the upper arms stationary, use the triceps to bring the weight back up to the starting position as you breathe out.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY['pecho','hombros']::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Dumbbell_Tricep_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Dumbbell_Tricep_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Dumbbell_Tricep_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Lying Triceps Press','lying-triceps-press','An isolation push exercise.',ARRAY['Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor.','Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. Tip: The arms should be perpendicular to the torso and the floor. The elbows should be tucked in. This is the starting position.','As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper arms and elbows stationary.','At that point, use the triceps to bring the weight back up to the starting position as you breathe out.','Repeat for the recommended amount of repetitions.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Triceps_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Triceps_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Triceps_Press/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Machine Triceps Extension','machine-triceps-extension','An isolation push exercise.',ARRAY['Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.','Perform the movement by extending the elbow, pulling your lower arm away from your upper arm.','Pause at the completion of the movement, and then slowly return the weight to the starting position.','Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.']::text[],'triceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Triceps_Extension/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Triceps_Extension/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Machine_Triceps_Extension/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('3/4 Sit-Up','34-sit-up','A compound pull exercise.',ARRAY['Lie down on the floor and secure your feet. Your legs should be bent at the knees.','Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position.','Flex your hips and spine to raise your torso toward your knees.','At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/3_4_Sit-Up/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/3_4_Sit-Up/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/3_4_Sit-Up/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Ab Crunch Machine','ab-crunch-machine','An isolation pull exercise.',ARRAY['Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.','At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.','After a second pause, slowly return to the starting position as you breathe in.','Repeat the movement for the prescribed amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ab_Crunch_Machine/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ab_Crunch_Machine/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ab_Crunch_Machine/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Ab Roller','ab-roller','A compound pull exercise.',ARRAY['Hold the Ab Roller with both hands and kneel on the floor.','Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.','Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.','After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[],'abdomen',ARRAY['hombros']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ab_Roller/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ab_Roller/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ab_Roller/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Advanced Kettlebell Windmill','advanced-kettlebell-windmill','An isolation push exercise.',ARRAY['Clean and press a kettlebell overhead with one arm.','Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell.','Lower yourself as far as possible.','Pause for a second and reverse the motion back to the starting position.']::text[],'abdomen',ARRAY['gluteos','piernas','hombros']::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Advanced_Kettlebell_Windmill/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Advanced_Kettlebell_Windmill/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Advanced_Kettlebell_Windmill/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Alternate Heel Touchers','alternate-heel-touchers','An isolation pull exercise.',ARRAY['Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.','Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.','Now go back slowly to the starting position as you inhale.','Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.','Continue alternating sides in this manner until all prescribed repetitions are done.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Heel_Touchers/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Heel_Touchers/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Heel_Touchers/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Barbell Ab Rollout - On Knees','barbell-ab-rollout---on-knees','A compound pull exercise.',ARRAY['Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.','Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.','Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.','After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[],'abdomen',ARRAY['espalda','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout_-_On_Knees/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout_-_On_Knees/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout_-_On_Knees/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Barbell Side Bend','barbell-side-bend','An isolation pull exercise.',ARRAY['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.','While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.','Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY['espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Side_Bend/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Side_Bend/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Side_Bend/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Bent Press','bent-press','A compound pull exercise.',ARRAY['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.','Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground.','Return to an upright position, with the kettlebell above your head. Return the kettlebell to the shoulder and repeat for the desired number of repetitions.']::text[],'abdomen',ARRAY['gluteos','piernas','espalda','hombros','triceps']::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Press/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Bosu Ball Cable Crunch With Side Bends','bosu-ball-cable-crunch-with-side-bends','An isolation pull exercise.',ARRAY['Connect a standard handle to each arm of a cable machine, and position them in the most downward position.','Grab a Bosu Ball and position it in front and center of the cable machine.','Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it.','With both hands, reach back and grab the handle of each cable.','With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees. Your hands should be at knee level.','Keep your arms straight and in-line with the upward angle of the cable. Elevate your torso in a crunching motion without dropping or bending your arms.','Maintain the rigid position with your arms. Slowly descend back to the starting position with your back arched around the Bosu Ball and your abdominals elongated.','Repeat the same series of movements to failure.','Once you reach failure, keep your abs tight and raise your torso into plank position so your back is elevated off the Bosu Ball.','Lower your arms down to your side; keep them straight. Start doing alternating side bends; reach for your heels! This finishing movement will focus on your obliques.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bosu_Ball_Cable_Crunch_With_Side_Bends/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Cable Crunch','cable-crunch','An isolation pull exercise.',ARRAY['Kneel below a high pulley that contains a rope attachment.','Grasp cable rope attachment and lower the rope until your hands are placed next to your face.','Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.','With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.','Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Crunch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Crunch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Crunch/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Cable Reverse Crunch','cable-reverse-crunch','An isolation pull exercise.',ARRAY['Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it.','Sit down with your feet toward the pulley and attach the cable to your ankles.','Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are.','With your hands behind your head, bring your knees inward to your torso and elevate your hips off the floor.','Pause for a moment and in a slow and controlled manner drop your hips and bring your legs back to the starting 90-degree angle. You should still have tension on your abs in the resting position.','Repeat the same movement to failure.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Reverse_Crunch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Reverse_Crunch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Reverse_Crunch/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Cable Seated Crunch','cable-seated-crunch','An isolation pull exercise.',ARRAY['Seat on a flat bench with your back facing a high pulley.','Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position.','With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this step.','As you inhale, go back to the initial position slowly.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Seated_Crunch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Seated_Crunch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Seated_Crunch/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Crunch - Hands Overhead','crunch---hands-overhead','An isolation pull exercise.',ARRAY['Lie on the floor with your back flat and knees bent with around a 60-degree angle between the hamstrings and the calves.','Keep your feet flat on the floor and stretch your arms overhead with your palms crossed. This will be your starting position.','Curl your upper body forward and bring your shoulder blades just off the floor. At all times, keep your arms aligned with your head, neck and shoulder. Don''t move them forward from that position. Exhale as you perform this portion of the movement and hold the contraction for a second.','Slowly lower down to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Crunch_-_Hands_Overhead/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Crunch_-_Hands_Overhead/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Crunch_-_Hands_Overhead/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Crunch - Legs On Exercise Ball','crunch---legs-on-exercise-ball','An isolation pull exercise.',ARRAY['Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle.','Place your feet three to four inches apart and point your toes inward so they touch.','Place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.','Push the small of your back down in the floor in order to better isolate your abdominal muscles. This will be your starting position.','Begin to roll your shoulders off the floor and continue to push down as hard as you can with your lower back. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. Breathe out as you execute this portion of the movement. Squeeze your abdominals hard at the top of the contraction and hold for a second. Tip: Focus on a slow, controlled movement. Refrain from using momentum at any time.','Slowly go back down to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Crunch_-_Legs_On_Exercise_Ball/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Crunch_-_Legs_On_Exercise_Ball/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Crunch_-_Legs_On_Exercise_Ball/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Crunches','crunches','An isolation pull exercise.',ARRAY['Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.','Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.','While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.','Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.','After the one second contraction, begin to come down slowly again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Crunches/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Crunches/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Crunches/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Decline Crunch','decline-crunch','An isolation pull exercise.',ARRAY['Secure your legs at the end of the decline bench and lie down.','Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.','While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.','Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.','After the one second contraction, begin to come down slowly again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Crunch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Crunch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Crunch/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Double Kettlebell Windmill','double-kettlebell-windmill','An isolation pull exercise.',ARRAY['Place a kettlebell in front of your front foot and clean and press a kettlebell overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward.','Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell.','Bending at the hip to one side, sticking your butt out, slowly lean until you can retrieve the kettlebell from the floor. Keep your eyes on the kettlebell that you hold over your head at all times.','Pause for a second after retrieving the kettlebell from the ground and reverse the motion back to the starting position.']::text[],'abdomen',ARRAY['gluteos','piernas','hombros','triceps']::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Kettlebell_Windmill/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Kettlebell_Windmill/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Kettlebell_Windmill/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Dumbbell Side Bend','dumbbell-side-bend','An isolation pull exercise.',ARRAY['Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.','While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.','Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.','Repeat for the recommended amount of repetitions and then change hands.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['mancuernas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Side_Bend/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Side_Bend/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Side_Bend/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Exercise Ball Crunch','exercise-ball-crunch','An isolation pull exercise.',ARRAY['Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head position).','Lower your torso into a stretch position keeping the neck stationary at all times. This will be your starting position.','With the hips stationary, flex the waist by contracting the abdominals and curl the shoulders and trunk upward until you feel a nice contraction on your abdominals. The arms should simply slide up the side of your legs if you have them at the side or just stay on top of your chest if you have them crossed. The lower back should always stay in contact with the ball. Exhale as you perform this movement and hold the contraction for a second.','As you inhale, go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Exercise_Ball_Crunch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Exercise_Ball_Crunch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Exercise_Ball_Crunch/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Exercise Ball Pull-In','exercise-ball-pull-in','A compound pull exercise.',ARRAY['Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position.','Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be your starting position.','While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles. Squeeze your abs and hold that position for a second.','Now slowly straighten your legs, rolling the ball back to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Exercise_Ball_Pull-In/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Exercise_Ball_Pull-In/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Exercise_Ball_Pull-In/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Flat Bench Lying Leg Raise','flat-bench-lying-leg-raise','An isolation pull exercise.',ARRAY['Lie with your back flat on a bench and your legs extended in front of you off the end.','Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position.','As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second.','Now, as you inhale, slowly lower your legs back down to the starting position.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flat_Bench_Lying_Leg_Raise/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flat_Bench_Lying_Leg_Raise/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flat_Bench_Lying_Leg_Raise/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Ankle On The Knee','ankle-on-the-knee','An isolation static exercise.',ARRAY['From a lying position, bend your knees and keep your feet on the floor.','Place your ankle of one foot on your opposite knee.','Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides.']::text[],'gluteos',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ankle_On_The_Knee/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ankle_On_The_Knee/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ankle_On_The_Knee/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Downward Facing Balance','downward-facing-balance','An isolation static exercise.',ARRAY['Lie facedown on top of an exercise ball.','While resting on your stomach on the ball, walk your hands forward along the floor and lift your legs, extending your elbows and knees.']::text[],'gluteos',ARRAY['abdomen','piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Downward_Facing_Balance/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Downward_Facing_Balance/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Downward_Facing_Balance/1.jpg']::text[],'Estático','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Hip Circles (prone)','hip-circles-prone','An isolation pull exercise.',ARRAY['Position yourself on your hands and knees on the ground. Maintaining good posture, raise one bent knee off of the ground. This will be your starting position.','Keeping the knee in a bent position, rotate the femur in an arc, attempting to make a big circle with your knee.','Perform this slowly for a number of repetitions, and repeat on the other side.']::text[],'gluteos',ARRAY['piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hip_Circles_prone/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hip_Circles_prone/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hip_Circles_prone/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('IT Band and Glute Stretch','it-band-and-glute-stretch','An isolation static exercise.',ARRAY['Loop a belt, rope, or band around one of your feet, and swing that leg across your body to the opposite side, keeping the leg extended as you lay on the ground. This will be your starting position.','Keeping your foot off of the floor, pull on the belt, using the tension to pull the toes up. Hold for 10-20 seconds, and repeat on the other side.']::text[],'gluteos',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/IT_Band_and_Glute_Stretch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/IT_Band_and_Glute_Stretch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/IT_Band_and_Glute_Stretch/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Iliotibial Tract-SMR','iliotibial-tract-smr','An isolation static exercise.',ARRAY['Lay on your side, with the bottom leg placed onto a foam roller between the hip and the knee. The other leg can be crossed in front of you.','Place as much of your weight as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground. Be sure to relax the muscles of the leg you are stretching.','Roll your leg over the foam from you hip to your knee, pausing for 10-30 seconds at points of tension. Repeat with the opposite leg.']::text[],'gluteos',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Iliotibial_Tract-SMR/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Iliotibial_Tract-SMR/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Iliotibial_Tract-SMR/1.jpg']::text[],'Estático','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Knee Across The Body','knee-across-the-body','An isolation static exercise.',ARRAY['Lie down on the floor with your right leg straight. Bend your left leg and lower it across your body, holding the knee down toward the floor with your right hand. (The knee doesn''t need to touch the floor if you''re tight.)','Place your left arm comfortably beside you and turn your head to the left. Imagine you have a weight tied to your tailbone. let your tailbone fall back toward the floor as your chest reaches in the opposite direction to stretch your lower back. Switch sides.']::text[],'gluteos',ARRAY['gluteos','espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Knee_Across_The_Body/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Knee_Across_The_Body/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Knee_Across_The_Body/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Lying Crossover','lying-crossover','An isolation static exercise.',ARRAY['Lie on your back with your legs extended.','Cross one leg over your body with the knee bent, attempting to touch the knee to the ground. Your partner should kneel beside you, holding your shoulder down with one hand and controlling the crossed leg with the other. this will be your starting position.','Attempt to raise the bent knee off of the ground as your partner prevents any actual movement.','After 10-20 seconds, relax the leg as your partner gently presses the knee towards the floor. Repeat with the other side.']::text[],'gluteos',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Crossover/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Crossover/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Crossover/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Lying Glute','lying-glute','An isolation static exercise.',ARRAY['Lie on your back with your partner kneeling beside you.','Flex the hip of one leg, raising it off of the floor. Rotate the leg so the foot is over the opposite hip, the lower leg perpendicular to your body. Your partner should hold the knee and ankle in place. This will be your starting position.','Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg.','After 10-20 seconds, completely relax as your partner gently pushes the ankle and knee towards your chest. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching.']::text[],'gluteos',ARRAY['gluteos']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Glute/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Glute/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Glute/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Monster Walk','monster-walk','A compound pull exercise.',ARRAY['Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart.','To begin, take short steps forward alternating your left and right foot.','After several steps, do just the opposite and walk backward to where you started.']::text[],'gluteos',ARRAY[]::muscle_group_type[],ARRAY['bandas','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Monster_Walk/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Monster_Walk/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Monster_Walk/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('One Knee To Chest','one-knee-to-chest','A compound static exercise.',ARRAY['Start off by lying on the floor.','Extend one leg straight and pull the other knee to your chest. Hold under the knee joint to protect the kneecap.','Gently tug that knee toward your nose.','Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg.']::text[],'gluteos',ARRAY['piernas','espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Knee_To_Chest/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Knee_To_Chest/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/One_Knee_To_Chest/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Physioball Hip Bridge','physioball-hip-bridge','A compound push exercise.',ARRAY['Lay on a ball so that your upper back is on the ball with your hips unsupported. Both feet should be flat on the floor, hip width apart or wider. This will be your starting position.','Begin by extending the hips using your glutes and hamstrings, raising your hips upward as you bridge.','Pause at the top of the motion and return to the starting position.']::text[],'gluteos',ARRAY['piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Physioball_Hip_Bridge/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Physioball_Hip_Bridge/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Physioball_Hip_Bridge/1.jpg']::text[],'Empuje','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Piriformis-SMR','piriformis-smr','An isolation static exercise.',ARRAY['Sit with your buttocks on top of a foam roll. Bend your knees, and then cross one leg so that the ankle is over the knee. This will be your starting position.','Shift your weight to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper glute. You may assist the stretch by using one hand to pull the bent knee towards your chest. Hold this position for 10-30 seconds, and then switch sides.']::text[],'gluteos',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Piriformis-SMR/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Piriformis-SMR/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Piriformis-SMR/1.jpg']::text[],'Estático','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Seated Glute','seated-glute','An isolation static exercise.',ARRAY['In a seated position with your knees bent, cross one ankle over the opposite knee. Your partner will stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.','Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.','Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds.']::text[],'gluteos',ARRAY['piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_Glute/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_Glute/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_Glute/1.jpg']::text[],'Estático','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Standing Hip Circles','standing-hip-circles','An isolation pull exercise.',ARRAY['Begin standing on one leg, holding to a vertical support.','Raise the unsupported knee to 90 degrees. This will be your starting position.','Open the hip as far as possible, attempting to make a big circle with your knee.','Perform this movement slowly for a number of repetitions, and repeat on the other side.']::text[],'gluteos',ARRAY['piernas']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Hip_Circles/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Hip_Circles/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Hip_Circles/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Thigh Abductor','thigh-abductor','An isolation push exercise.',ARRAY['To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.','Slowly press against the machine with your legs to move them away from each other while exhaling.','Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.','Repeat for the recommended amount of repetitions.']::text[],'gluteos',ARRAY['gluteos']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Thigh_Abductor/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Thigh_Abductor/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Thigh_Abductor/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[]),
('Windmills','windmills','An isolation pull exercise.',ARRAY['Lie on your back with your arms extended out to the sides and your legs straight. This will be your starting position.','Lift one leg and quickly cross it over your body, attempting to touch the ground near the opposite hand.','Return to the starting position, and repeat with the opposite leg. Continue to alternate for 10-20 repetitions.']::text[],'gluteos',ARRAY['gluteos','piernas','espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Windmills/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Windmills/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Windmills/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-15',60,ARRAY[]::text[])
